/**
 * Per-functie letter context. The actual letter body is generated by combining
 * this with the CV example's persona data — so we get realistic letters for
 * every functie without hand-writing 20 variants.
 */
interface LetterContext {
  /** Target vacancy title (often slightly different from the candidate's current role) */
  vacancyTitle: string;
  /** Fictional company they're applying to */
  recipientCompany: string;
  recipientCity: string;
  /** Optional contact person */
  contactName?: string;
  /** Hooks to weave into the body — concrete to the functie */
  hookA: string;
  hookB: string;
  /** Optional availability statement */
  availability?: string;
}

