/**
 * Build a CoverLetterData object from a CV example, using a per-functie letter
 * context. The candidate's name, address, and contact info come from the CV
 * example; the letter body is composed from the hooks + a generic structure.
 */
export function buildExampleLetter(example: FunctieExample): CoverLetterData {
  const ctx = LETTER_CONTEXTS[example.slug];
  if (!ctx) return createEmptyCoverLetter();

  const now = new Date('2026-05-15').toISOString();
  const fullName = `${example.cv.personal.firstName} ${example.cv.personal.lastName}`.trim();
  const greeting = ctx.contactName ? `Geachte ${ctx.contactName},` : 'Geachte heer / mevrouw,';

  const opening = `Met veel interesse heb ik kennis genomen van de vacature voor ${ctx.vacancyTitle} bij ${ctx.recipientCompany}. De combinatie van uw organisatie en deze functie sluit aan op de richting waar ik mijn carrière naartoe wil ontwikkelen.`;

  const body = `In mijn huidige rol als ${example.cv.experience[0]?.jobTitle ?? 'professional'}${
    example.cv.experience[0]?.company ? ` bij ${example.cv.experience[0].company}` : ''
  } heb ik ervaring opgedaan met ${ctx.hookA}. Daarnaast richt ik me actief op ${ctx.hookB} — voor mij is dat een onmisbaar onderdeel van het vak. Ik herken in de vacaturetekst van ${ctx.recipientCompany} de manier waarop deze elementen samenkomen.`;

  const closing = `${
    ctx.availability ?? 'Ik licht mijn motivatie graag toe in een persoonlijk gesprek.'
  } U kunt mij bereiken via ${example.cv.personal.email}${
    example.cv.personal.phone ? ` of ${example.cv.personal.phone}` : ''
  }.`;

  return {
    id: `example-letter-${example.slug}`,
    createdAt: now,
    updatedAt: now,
    sender: {
      firstName: example.cv.personal.firstName,
      lastName: example.cv.personal.lastName,
      email: example.cv.personal.email,
      phone: example.cv.personal.phone,
      address: example.cv.personal.address || '',
      city: example.cv.personal.city,
      postalCode: example.cv.personal.postalCode || '',
    },
    recipient: {
      contactName: ctx.contactName ?? '',
      contactTitle: '',
      company: ctx.recipientCompany,
      city: ctx.recipientCity,
    },
    vacancyTitle: ctx.vacancyTitle,
    vacancyReference: '',
    date: '2026-05-15',
    letterCity: example.cv.personal.city,
    greeting,
    opening,
    body,
    closing,
    signature: 'Met vriendelijke groet,',
    meta: {
      selectedTemplate: 'modern',
      selectedColorScheme: (example.colorSchemeId as ColorSchemeId) || 'emerald',
    },
  };
}

export function hasLetterContext(slug: string): boolean {
  return slug in LETTER_CONTEXTS;
}
